// Сутки в часовому поясі браузера — для особистих сторінок (історія трейдів,
// аналітика). Публічна головна рахує доби в UTC (utcDay.ts). Бекенду все
// одно, які межі прийшли: він бере угоди, ЗАКРИТІ між ними.
// Північ місцевої доби, в яку потрапляє ts.
export const localDayStart = (ts) => {
    const date = new Date(ts);
    date.setHours(0, 0, 0, 0);
    return date.getTime();
};
// Доба на n днів раніше/пізніше — календарем (setDate), а не ±24 год: у день
// переходу на літній/зимовий час доба триває 23 чи 25 годин.
export const shiftLocalDay = (ts, n) => {
    const date = new Date(localDayStart(ts));
    date.setDate(date.getDate() + n);
    return date.getTime();
};
// Перша й остання мілісекунда місцевої доби — обидві включно, як фільтри API.
export const localDayRange = (ts) => {
    const start_ts = localDayStart(ts);
    return { start_ts, end_ts: shiftLocalDay(start_ts, 1) - 1 };
};
export const formatLocalDay = (ts, locale) => new Date(ts).toLocaleDateString(locale);
